<script setup>import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';defineProps({orders:Object,filters:Object});const statuses=['pending','confirmed','preparing','out_for_delivery','delivered','cancelled'];function setStatus(id,status){router.patch('/admin/orders/'+id+'/status',{status},{preserveScroll:true});}</script>
<template><Layout><div><p class="eyebrow">Operations</p><h1 class="serif text-5xl font-bold">Orders</h1></div><div class="card mt-6"><div class="grid gap-3 md:grid-cols-[1fr_180px_auto]"><input :value="filters?.search" @change="router.get('/admin/orders',{search:$event.target.value,status:filters?.status})" placeholder="Search order, name or phone" class="field"><select :value="filters?.status" @change="router.get('/admin/orders',{search:filters?.search,status:$event.target.value})" class="field"><option value="">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{s.replaceAll('_',' ')}}</option></select><button class="pill" @click="router.get('/admin/orders')">Reset</button></div></div><div class="mt-5 space-y-3"><article v-for="o in orders.data" :key="o.id" class="card"><div class="flex flex-col gap-4 md:flex-row md:items-center md:justify-between"><div><Link :href="'/admin/orders/'+o.id" class="serif text-2xl font-bold underline-offset-4 hover:underline">{{o.order_number}}</Link><p class="mt-1 text-sm opacity-60">{{o.customer_name}} · {{o.phone}} · {{o.area}}</p><p class="mt-3 text-sm">{{o.address}}</p></div><div class="md:text-right"><b class="text-lg">{{o.total}} EGP</b><select :value="o.status" @change="setStatus(o.id,$event.target.value)" class="field mt-3"><option v-for="s in statuses" :key="s" :value="s">{{s.replaceAll('_',' ')}}</option></select></div></div></article></div></Layout></template>
